/* Reset & base */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0f0;
  --accent: #6c5ce7;
  --tile-colors: #e74c3c, #3498db, #2ecc71, #f1c40f;
  --tile-size: clamp(48px, 18vw, 72px);
  --gap: 8px;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 20px;
  padding: 24px 20px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  text-align: center;
}

h1 {
  font-size: 1.6rem;
  margin-bottom: 8px;
  font-weight: 600;
}

.instructions {
  font-size: 1rem;
  margin-bottom: 20px;
  opacity: 0.8;
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  gap: 12px;
}

#swap-count {
  font-size: 1.1rem;
  font-weight: 500;
}

#shuffle-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 12px;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-height: 48px;
}

#shuffle-btn:hover { background: #5a4bd1; }
#shuffle-btn:focus-visible { outline: 3px solid #fff; outline-offset: 2px; }
#shuffle-btn:active { transform: scale(0.96); }

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  justify-content: center;
  margin: 0 auto 16px;
  width: fit-content;
}

.tile {
  width: var(--tile-size);
  height: var(--tile-size);
  border-radius: 12px;
  border: 2px solid rgba(255,255,255,0.2);
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.2s, border-color 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
  font-weight: 600;
  color: rgba(255,255,255,0.7);
  user-select: none;
}

.tile:hover { transform: scale(1.05); box-shadow: 0 0 12px rgba(255,255,255,0.3); }
.tile:focus-visible { outline: 3px solid #fff; outline-offset: 2px; }
.tile:active { transform: scale(0.95); }
.tile.selected { border-color: #fff; box-shadow: 0 0 16px #fff; }

.tile[data-color="0"] { background: #e74c3c; }
.tile[data-color="1"] { background: #3498db; }
.tile[data-color="2"] { background: #2ecc71; }
.tile[data-color="3"] { background: #f1c40f; color: #333; }

.solved {
  font-size: 1.4rem;
  font-weight: 700;
  color: #2ecc71;
  margin-top: 8px;
  animation: pulse 0.6s ease;
}

@keyframes pulse {
  0% { transform: scale(0.9); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

[hidden] { display: none !important; }

@media (max-width: 400px) {
  .card { padding: 16px 12px; }
  h1 { font-size: 1.3rem; }
  :root { --tile-size: clamp(40px, 20vw, 60px); --gap: 6px; }
}

(function() {
  'use strict';

  const COLORS = 4;
  const SIZE = 4;
  const TOTAL = SIZE * SIZE;

  const boardEl = document.getElementById('board');
  const swapCountEl = document.getElementById('swap-count');
  const shuffleBtn = document.getElementById('shuffle-btn');
  const solvedMsg = document.getElementById('solved-message');

  let grid = [];
  let swapCount = 0;
  let selectedIndex = null;
  let solved = false;

  function createSolvedGrid() {
    const g = [];
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        g.push(r);
      }
    }
    return g;
  }

  function shuffleArray(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function isSolved() {
    for (let r = 0; r < SIZE; r++) {
      const first = grid[r * SIZE];
      for (let c = 1; c < SIZE; c++) {
        if (grid[r * SIZE + c] !== first) return false;
      }
    }
    return true;
  }

  function areAdjacent(i, j) {
    const r1 = Math.floor(i / SIZE), c1 = i % SIZE;
    const r2 = Math.floor(j / SIZE), c2 = j % SIZE;
    return (Math.abs(r1 - r2) + Math.abs(c1 - c2)) === 1;
  }

  function render() {
    boardEl.innerHTML = '';
    for (let i = 0; i < TOTAL; i++) {
      const tile = document.createElement('button');
      tile.type = 'button';
      tile.className = 'tile';
      tile.dataset.index = i;
      tile.dataset.color = grid[i];
      tile.setAttribute('role', 'gridcell');
      const colorName = ['Red', 'Blue', 'Green', 'Yellow'][grid[i]];
      tile.setAttribute('aria-label', `Tile ${i + 1}, ${colorName}`);
      tile.textContent = colorName[0];
      tile.addEventListener('click', onTileClick);
      boardEl.appendChild(tile);
    }
    updateStatus();
  }

  function updateStatus() {
    swapCountEl.textContent = `Swaps: ${swapCount}`;
  }

  function onTileClick(e) {
    if (solved) return;
    const idx = Number(e.currentTarget.dataset.index);

    if (selectedIndex === null) {
      selectedIndex = idx;
      e.currentTarget.classList.add('selected');
      return;
    }

    if (selectedIndex === idx) {
      selectedIndex = null;
      e.currentTarget.classList.remove('selected');
      return;
    }

    if (areAdjacent(selectedIndex, idx)) {
      [grid[selectedIndex], grid[idx]] = [grid[idx], grid[selectedIndex]];
      swapCount++;
      selectedIndex = null;
      render();
      if (isSolved()) {
        solved = true;
        solvedMsg.hidden = false;
      }
    } else {
      boardEl.children[selectedIndex].classList.remove('selected');
      selectedIndex = idx;
      e.currentTarget.classList.add('selected');
    }
  }

  function startNewGame() {
    grid = shuffleArray(createSolvedGrid());
    if (isSolved()) {
      return startNewGame();
    }
    swapCount = 0;
    selectedIndex = null;
    solved = false;
    solvedMsg.hidden = true;
    render();
  }

  shuffleBtn.addEventListener('click', startNewGame);

  startNewGame();
})();
